const fs = require('fs');
const path = require('path');

// Check all required files exist
const requiredFiles = [
  'index.html',
  'css/app.css',
  'js/app.js',
  'readme.md',
  'node_modules/todomvc-common/base.css',
  'node_modules/todomvc-app-css/index.css'
];

let missing = [];
for (const file of requiredFiles) {
  if (!fs.existsSync(file)) {
    missing.push(file);
  }
}

if (missing.length === 0) {
  console.log('All required files exist');
} else {
  console.error('Missing files:', missing);
}

// Check index.html contains required elements
const html = fs.readFileSync('index.html', 'utf8');
const requiredElements = [
  'class=\"todoapp\"',
  'class=\"header\"',
  'class=\"new-todo\"',
  'class=\"main\"',
  'class=\"todo-list\"',
  'class=\"footer\"',
  'class=\"todo-count\"',
  'class=\"filters\"',
  'class=\"clear-completed\"'
];

let missingElements = [];
for (const elem of requiredElements) {
  if (!html.includes(elem)) {
    missingElements.push(elem);
  }
}

if (missingElements.length === 0) {
  console.log('HTML contains all required elements');
} else {
  console.error('HTML missing elements:', missingElements);
}
"

node -e "
const fs = require('fs');
const js = fs.readFileSync('js/app.js', 'utf8');

// Check for required functionality
const requiredFunctions = [
  'loadTodos',
  'saveTodos', 
  'addTodo',
  'toggleTodo',
  'deleteTodo',
  'editTodo',
  'clearCompleted',
  'toggleAll',
  'getFilteredTodos',
  'render'
];

let missingFunctions = [];
for (const func of requiredFunctions) {
  if (!js.includes(func + '(')) {
    missingFunctions.push(func);
  }
}

if (missingFunctions.length === 0) {
  console.log('JavaScript contains all required functions');
} else {
  console.error('JavaScript missing functions:', missingFunctions);
}

// Check localStorage usage
if (js.includes('localStorage')) {
  console.log('JavaScript uses localStorage for persistence');
} else {
  console.error('JavaScript does not use localStorage');
}

// Check for keyboard handling
if (js.includes('keydown') && js.includes('Enter')) {
  console.log('JavaScript handles keyboard events');
} else {
  console.error('JavaScript missing keyboard handling');
}
