document.querySelector('.clear-completed').click();
check('1 todo after clear completed', document.querySelectorAll('.todo-list li').length === 1);
check('count shows 1 item left after clear', document.querySelector('.todo-count strong').textContent === '1');

// 5) Delete
document.querySelector('.todo-list li .destroy').click();
