check('footer hidden after all deleted', footer.style.display === 'none');

// 6) Persistence
input.value = 'Persistent Todo';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
const stored = JSON.parse(window.localStorage.getItem('todos-vanillajs'));
check('localStorage has 1 item', stored.length === 1);
check('localStorage title correct', stored[0].title === 'Persistent Todo');
check('localStorage completed is false', stored[0].completed === false);

// 7) Trim input
input.value = '   Trimmed Todo   ';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
check('trimmed todo added correctly', document.querySelector('.todo-list li:last-child label').textContent === 'Trimmed Todo');

// 8) Empty input ignored
