input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
check('empty input ignored', document.querySelectorAll('.todo-list li').length === 2);

// 9) Escape cancels edit
const firstLi = document.querySelector('.todo-list li');
const firstLabel = firstLi.querySelector('label');
firstLabel.dispatchEvent(new window.Event('dblclick', { bubbles: true }));
check('editing class added', firstLi.classList.contains('editing'));
const editInput = firstLi.querySelector('.edit');
