document.dispatchEvent(new window.Event('DOMContentLoaded', { bubbles: true }));
window.dispatchEvent(new window.Event('load'));

// Listen for hashchange as the test world does
document.addEventListener('click', (e) => {
  const a = e.target && e.target.closest ? e.target.closest('a[href^=\"#\"]') : null;
  if (!a) return;
  const next = a.getAttribute('href');
  if (window.location.hash !== next) {
    window.location.hash = next;
    window.dispatchEvent(new window.Event('hashchange'));
  }
}, true);

const main = document.querySelector('.main');
const footer = document.querySelector('.footer');
let passed = 0;
let failed = 0;

function check(label, cond) {
  if (cond) { passed++; console.log('  ✓ ' + label); }
  else { failed++; console.log('  ✗ ' + label); }
}

function navigate(hash) {
  if (window.location.hash === hash) return;
  window.location.hash = hash;
  window.dispatchEvent(new window.Event('hashchange'));
}

const input = document.querySelector('.new-todo');

// --- Add 3 todos: active, completed, active ---
input.value = 'Active 1';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
input.value = 'Will Complete';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
input.value = 'Active 2';
input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));

check('3 todos', document.querySelectorAll('.todo-list li').length === 3);
check('count shows 3', document.querySelector('.todo-count strong').textContent === '3');

