navigate('#/active');
check('Active filter: 2 visible', document.querySelectorAll('.todo-list li').length === 2);
check('Active filter: completed todo hidden', document.querySelectorAll('.todo-list li')[0].querySelector('label').textContent === 'Active 1');
check('Active filter: second visible is Active 2', document.querySelectorAll('.todo-list li')[1].querySelector('label').textContent === 'Active 2');

// Navigate to Completed
navigate('#/completed');
check('Completed filter: 1 visible', document.querySelectorAll('.todo-list li').length === 1);
check('Completed filter: shows Will Complete', document.querySelector('.todo-list li label').textContent === 'Will Complete');

// Navigate to All
navigate('#/');
check('All filter: 3 visible', document.querySelectorAll('.todo-list li').length === 3);

// --- Clear completed button visibility ---
check('Clear completed visible (has completed)', footer.querySelector('.clear-completed').style.display !== 'none');

// Complete all
